type State = {operator?:Row;organization:Row[]; group:Row[]; athlete:Row[]; membership:Row[]; measurement:Row[]; protocol:Row[]; test:Row[]};
const empty:State = {organization:[],group:[],athlete:[],membership:[],measurement:[],protocol:[],test:[]};
