 const payload=()=>({athlete_id:draft.athlete_id,protocol_id:draft.protocol_id,trace_hash:trace?.hash,date:draft.date,notes:draft.notes,settings:{...Object.fromEntries(['offset_s','end_s','weight_kg','height_cm','rest_hr','rest_after_s','rpe','threshold_w','threshold_coefficient','fthr_bpm','ftp_w','fc_max_reference_bpm'].map(k=>[k,draft[k]===''||draft[k]==null?null:Number(draft[k])])),weight_source:draft.weight_source||'dichiarato',measurement_id:draft.measurement_id||null,threshold_source:draft.threshold_source||'dichiarato',recovery_manual:draft.recovery_manual||[],lactate:draft.lactate||[],zone_schemes:draft.zone_schemes,...Object.fromEntries(['lactate_levels','preset_id','excluded_intervals','alignment_markers','conditions','gas_hash','gas_offset_s','ventilatory_markers','vo2max_verification','threshold_calibration','rpe_scale','custom_values','extra_fields'].filter(k=>draft[k]!=null).map(k=>[k,draft[k]]))}});
